import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

function readArtifact(contractName) {
  const artifactPath = path.join(
    root,
    "artifacts",
    "contracts",
    `${contractName}.sol`,
    `${contractName}.json`,
  );
  const artifact = JSON.parse(fs.readFileSync(artifactPath, "utf8"));
  if (
    !Array.isArray(artifact.abi) ||
    typeof artifact.bytecode !== "string" ||
    !artifact.bytecode.startsWith("0x") ||
    artifact.bytecode.length <= 2
  ) {
    throw new Error(`Invalid Hardhat artifact for ${contractName}`);
  }
  return { abi: artifact.abi, bytecode: artifact.bytecode };
}

const target = path.join(
  root,
  "frontend",
  "generated",
  "mainnetPrimaryResolutionDeployment.ts",
);
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(
  target,
  [
    "// Generated from Hardhat artifacts during the build.",
    "// Do not edit this file manually.",
    "export const mainnetPrimaryResolutionDeploymentArtifacts = " +
      JSON.stringify({
        forwardResolver: readArtifact("XNSResolverV2"),
        reverseResolver: readArtifact("XNSReverseResolverV3"),
        registrar: readArtifact("XNSPrimaryRegistrar"),
        multichainResolver: readArtifact("XNSMultichainResolverV2"),
      }) +
      " as const;",
    "",
  ].join("\n"),
);
console.log("Generated", path.relative(root, target));
